import java.util.*;

public class Solution {
    public boolean isMonotonic(List<Integer> list) throws IllegalArgumentException {
        if (list == null || list.size() <= 1) {
            throw new IllegalArgumentException("List should have at least two elements for comparison.");
        }

        int initialComparison = list.get(0).compareTo(list.get(1));
        if (initialComparison == 0) {
            // Both the elements are the same, so we find the next different elements in the list
            Optional<Integer> comparisonResult = findFirstNonZeroComparisonFromIndex(list, 2);
            if (comparisonResult.isPresent()) {
                initialComparison = comparisonResult.get();
            }
        }

        if (initialComparison < 0) {
            return isStrictlyIncreasing(list);
        } else {
            return isStrictlyDecreasing(list);
        }
    }

    private boolean isStrictlyIncreasing(List<Integer> list) {
        for (int i = 0; i + 1 < list.size(); i++) {
            if (list.get(i).compareTo(list.get(i + 1)) > 0) {
                return false;
            }
        }
        return true;
    }

    private boolean isStrictlyDecreasing(List<Integer> list) {
        for (int i = 0; i + 1 < list.size(); i++) {
            if (list.get(i).compareTo(list.get(i + 1)) < 0) {
                return false;
            }
        }
        return true;
    }

    private Optional<Integer> findFirstNonZeroComparisonFromIndex(List<Integer> list, int fromIndex) {
        for (int i = fromIndex; i + 1 < list.size(); i++) {
            int comparison = list.get(i).compareTo(list.get(i + 1));
            if (comparison != 0) {
                return Optional.of(comparison);
            }
        }
        return Optional.empty();
    }
}

