use strict;
use warnings;

sub is_monotonic {
    my @list = @_;

    die "List should have at least two elements for comparison."
        if @list < 2;

    my $initial_comparison = $list[0] <=> $list[1];

    if($initial_comparison == 0) {
        my $comparison_result = find_first_non_zero_comparison_from_index(@list, 2);
        $initial_comparison = $comparison_result if defined $comparison_result;
    }

    if ($initial_comparison < 0) {
        return is_strictly_increasing(@list);
    } else {
        return is_strictly_decreasing(@list);
    }
}

sub is_strictly_increasing {
    my @list = @_;

    for my $i (0 .. $#list - 1) {
        return 0 if $list[$i] > $list[$i + 1];
    }

    return 1;
}

sub is_strictly_decreasing {
    my @list = @_;

    for my $i (0 .. $#list - 1) {
        return 0 if $list[$i] < $list[$i + 1];
    }

    return 1;
}

sub find_first_non_zero_comparison_from_index {
    my @list = @_;
    my $from_index = pop @list;

    for my $i ($from_index .. $#list - 1) {
        my $comparison = $list[$i] <=> $list[$i + 1];

        if($comparison != 0) {
            return $comparison;
        }
    }

    return undef;
}
