```rust
// src/database/resource.rs

pub struct ResourceManager {
    total_resources: u32,
    allocated_resources: u32,
    resource_usage: Vec<u32>,
}

impl ResourceManager {
    pub fn new(total_resources: u32) -> Self {
        ResourceManager {
            total_resources,
            allocated_resources: 0,
            resource_usage: vec![0; total_resources as usize],
        }
    }

    pub fn allocate_resources(&mut self, amount: u32) -> Result<(), String> {
        if self.allocated_resources + amount > self.total_resources {
            return Err("Insufficient resources available".to_string());
        }
        self.allocated_resources += amount;
        Ok(())
    }

    pub fn deallocate_resources(&mut self, amount: u32) -> Result<(), String> {
        if self.allocated_resources < amount {
            return Err("Cannot deallocate more resources than allocated".to_string());
        }
        self.allocated_resources -= amount;
        Ok(())
    }

    pub fn track_resource_usage(&mut self, resource_id: usize, usage: u32) -> Result<(), String> {
        if resource_id >= self.total_resources as usize {
            return Err("Invalid resource ID".to_string());
        }
        self.resource_usage[resource_id] += usage;
        Ok(())
    }
}
```

