```javascript
function generateRandomKey() {
    let key = '';
    const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';

    for (let i = 0; i < 10; i++) {
        key += characters.charAt(Math.floor(Math.random() * characters.length));
    }

    return key;
}

function generateRandomValue(depth = 0) {
    let value = {};
    const keys = Array.from({length: 5}, generateRandomKey);

    keys.forEach(key => {
        if (depth < 3 && Math.random() > 0.5) {
            value[key] = generateRandomValue(depth + 1);
        } else {
            value[key] = Math.random().toString(36).substr(2, 5);
        }
    });

    return value;
}

function generateRandomDict() {
    let dict = {};
    let keys = [];

    while (keys.length < 10) {
        let newKey = generateRandomKey();

        if (!keys.includes(newKey)) {
            keys.push(newKey);
            dict[newKey] = generateRandomValue();
        }
    }

    return dict;
}

console.log(generateRandomDict());
