    public DateTime ReleaseDate { get; set; }
    public string Overview { get; set; }
    public double Rating { get; set; }
}

// Define a service interface for retrieving movie data
public interface IMovieService
{
    Task<List<Movie>> GetNowPlayingMovies();
    Task<Movie> GetMovieByTitle(string title);
}

// Implement the movie recommendation system
public class MovieRecommendationSystem
{
    private readonly IMovieService _service;
    private List<Movie> _nowPlaying;

    public MovieRecommendationSystem(IMovieService service)
    {
        _service = service;
    }

    // Retrieve now playing movies and assign them to _nowPlaying
    public async Task RetrieveNowPlayingMovies()
    {
        try
        {
            var response = await _service.GetNowPlayingMovies();
            _nowPlaying = response ?? new List<Movie>();
        }
        catch (Exception ex)
        {
            // Handle exception, log error, or display a message to the user
        }
    }

    // Display the list of now playing movies to the user
    public void DisplayNowPlayingMovies()
    {
        foreach (var movie in _nowPlaying)
        {
            Console.WriteLine($"Title: {movie.Title}, Release Date: {movie.ReleaseDate}, Rating: {movie.Rating}");
        }
    }

    // Search for a specific movie by its title and display detailed information
    public async Task DisplayMovieDetails(string title)
    {
        try
        {
            var movie = await _service.GetMovieByTitle(title);
            if (movie != null)
            {
                Console.WriteLine($"Title: {movie.Title}");
                Console.WriteLine($"Release Date: {movie.ReleaseDate}");
                Console.WriteLine($"Overview: {movie.Overview}");
                Console.WriteLine($"Rating: {movie.Rating}");
            }
            else
            {
                Console.WriteLine("Movie not found");
            }
        }
        catch (Exception ex)
        {
            // Handle exception, log error, or display a message to the user
        }
    }
}
```
In the solution, we define a `Movie` class to represent movie details and an `IMovieService` interface for retrieving movie data. The `MovieRecommendationSystem` class implements the movie recommendation system with methods to retrieve now playing movies, display them to the user, and search for detailed movie information. Error handling is included to handle exceptions and edge cases.

