console.log(trapezoidArea(3, 7, 5, 5)); // Expected: 21.66
console.log(trapezoidArea(4, 'a', 5, 5)); // Expected: Error: inputs must be positive real numbers.
console.log(trapezoidArea(4, 4, 5, 5)); // Expected: Error: bases cannot be equal.
