        for (int x = 0; x < N / 2; x++) {
            for (int y = x; y < N - x - 1; y++) {
                int temp = matrix[x][y];
                matrix[x][y] = matrix[N - 1 - y][x];
                matrix[N - 1 - y][x] = matrix[N - 1 - x][N - 1 - y];
