```python
from functools import lru_cache

@lru_cache(maxsize=None)
def factorial(n):
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    if n == 0:
        return 1
    else:
        return n * factorial(n-1)

print(factorial(7))
```

