```rust
struct MovingAverage {
    window: Vec<f64>,
    size: usize,
    sum: f64,
}

impl MovingAverage {
    fn new(size: usize) -> Self {
        MovingAverage {
            window: Vec::new(),
            size,
            sum: 0.0,
        }
    }

    fn next(&mut self, val: f64) -> f64 {
        if self.window.len() < self.size {
            self.window.push(val);
            self.sum += val;
        } else {
            let first = self.window.remove(0);
            self.sum = self.sum - first + val;
            self.window.push(val);
        }
        self.sum / self.window.len() as f64
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_moving_average_2() {
        let mut m = MovingAverage::new(3);
        assert_eq!(m.next(1.0), 1.0);
        assert_eq!(m.next(10.0), 5.5);
        assert_eq!(m.next(3.0), 4.666666666666667);
        assert_eq!(m.next(5.0), 6.0);
    }
}
```
