유형 트랜잭션 구조체 {
	해시 문자열 `gorm:"primaryKey;type:varchar(66)" json:"hash"`
	트랜잭션 인덱스 int `gorm:"primaryKey" json:"transaction_index"`
	Nonce int `json:"nonce"`
	블록 타임스탬프 *플로트64 `gorm:"index" json:"block_timestamp"`
	BlockNumber int `gorm:"index" json:"block_number"`
	FromAddress 문자열 `gorm:"index;type:varchar(42)" json:"from_address"`
	ToAddress *string `gorm:"index;type:varchar(42);default:NULL" json:"to_address"`
	값 float64 `json:"value"`
	가스 플로트64 `json:"gas"`
	가스 가격 float64 `json:"gas_price"`
	입력 문자열 `gorm:"type:text" json:"input"`
	MaxFeePerGas *float64 `json:"max_fee_per_gas"`
	MaxPriorityFeePerGas *float64 `json:"max_priority_fee_per_gas"`
	트랜잭션 유형 int `json:"트랜잭션 유형"`
}

func main() {
	// 명령줄 인자를 파싱합니다.
	startBlock := flag.Int("시작", 0, "시작 블록 번호")
	endBlock := flag.Int("end", 0, "종료 블록 번호")
	flag.Parse()

