	db, err := gorm.Open(postgres.Open(dsn), &gorm.Config{})
	if err != nil {
 log.Fatalf("데이터베이스에 연결하는 동안 오류가 발생했습니다: %v", err)
	}

	// 스키마 마이그레이션
	err = db.AutoMigrate(&Transaction{})
	if err != nil {
 log.Fatalf("스키마 마이그레이션 중 오류: %v", err)
	}

	cmd := exec.Command("polygonetl", "stream", "--provider-uri", "https://polygon-rpc.com", "-e", "transaction")

	// 명령의 표준 출력 스트림에 대한 파이프를 생성합니다.
	stdoutPipe, err := cmd.StdoutPipe()
	if err != nil {
 log.Fatalf("stdout 파이프 생성 중 오류: %v", err)
	}

	// 명령 시작
	err = cmd.Start()
	if err != nil {
 log.Fatalf("명령 시작 중 오류: %v", err)
	}

	scanner := bufio.NewScanner(stdoutPipe)

	// SQL 삽입을 위한 배치 크기
	const batchSize = 100

	// 사용할 작업자 고루틴의 개수
	const numWorkers = 10

	// 워커에게 트랜잭션을 전송하고 결과를 수집하기 위한 채널
