In C, you might not have the luxury of list comprehension, string concatenation and built-in regex libraries. But C has other tools like loops, character array manipulation, and its standard library functions which can be used to achieve the same results. Below is an implementation in C

```c
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

// Helper function to remove unwanted characters and convert to lowercase
void cleanString(const char* src, char* dest) {
    for (; *src; ++src)
    {
        if (isalpha(*src))
            *dest++ = tolower((unsigned char)(*src));
    }
    *dest = 0;
}

// Function to clean, mix, reverse and sort all strings
void custom_mix_strings(char** input, size_t num_strings, char** output) {
    // Find the maximum length and clean input strings
    size_t max_length = 0;
    char** cleaned_strings = malloc(sizeof(char*) * num_strings);
    for (size_t i = 0; i < num_strings; ++i) {
        cleaned_strings[i] = malloc(strlen(input[i]) + 1);
        cleanString(input[i], cleaned_strings[i]);
        if (strlen(cleaned_strings[i]) > max_length)
            max_length = strlen(cleaned_strings[i]);
    }
    // Initialize result string array
    for (size_t i = 0; i < max_length; ++i) {
        output[i] = malloc(num_strings + 1);
        output[i][0] = 0;
    }
    // Swap characters alternately between strings
    for (size_t i = 0; i < max_length; ++i) {
        for (size_t j = 0; j < num_strings; ++j) {
            if (i < strlen(cleaned_strings[j])) {
                output[i % max_length][j] = cleaned_strings[j][i];
                output[i % max_length][j + 1] = 0;
            }
        }
    }
    // Reverse all strings
    for (size_t i = 0; i < max_length; ++i) {
        for (size_t j = 0, k = strlen(output[i]) - 1; j < k; ++j, --k) {
            char temp = output[i][j];
            output[i][j] = output[i][k];
            output[i][k] = temp;
        }
    }
    // Sort all strings by length (bubble sort)
    for (size_t i = 0; i < max_length; ++i) {
        for (size_t j = i + 1; j < max_length; ++j) {
            if (strlen(output[i]) > strlen(output[j])) {
                char* temp = output[i];
                output[i] = output[j];
                output[j] = temp;
            }
        }
    }
    // Free cleaned strings
    for (size_t i = 0; i < num_strings; ++i)
        free(cleaned_strings[i]);
    free(cleaned_strings);
}
```

Please note that this code does not handle memory deallocation for the output. You should deallocate the memory after you are done using the output. Furthermore, it also does not check if the `input` strings contain only valid UTF-8 characters, which might be necessary depending on your use case.

