class Solution {
    func rob(_ root: TreeNode?) -> Int {
        guard let root = root else {
            return 0
        }
        var arr = [Int]()
        helper(root, 0, &arr)
        var last = 0
        var last2 = 0
        for i in 0..<arr.count {
            arr[i] = max(last, arr[i]+last2)
            (last, last2) = (arr[i], last)
        }
        return max(arr[arr.count-1], arr[arr.count-2])
    }

    func helper(_ node: TreeNode?, _ level: Int, _ arr: inout [Int]) {
        guard let node = node else {
            return
        }
        if level >= arr.count {
            arr.append(0)
        }
        arr[level] += node.val
        helper(node.left, level + 2, &arr)
        helper(node.right, level + 2, &arr)
    }
}
```

