class SchemaParser:
    def __init__(self, comment_schema):
        self.comment_schema = comment_schema

    def parse_data(self, response, schema=None, comment=None):
        if schema:
            # If a schema is defined, then try to parse it with that
            return schema.parse_obj(response)
        elif comment:
            return self.comment_schema.parse_obj(response)
        elif 'type' in response:
            # Otherwise, check if the incoming type is within the dict of loaded schemas
            types = response['type'].split('/')
            for t in reversed(types):
                if t in SCHEMAS:
                    return SCHEMAS[t].parse_obj(response)
        # If no schema or comment is provided, and type is not found in loaded schemas, return the response as a dictionary
        return response
