#include <string>
#include <벡터>
#include <unordered_map>
#include <메모리>

열거형 VarType {
 INTEGER,
 STRING,
 ARRAY,
 MAP
};

클래스 Var {
public:
 가상 ~Var() {}
 가상 VarType getType() const = 0;
};

IntVar 클래스 : public Var {
public:
 IntVar(int i) : value(i) {}
 int 값입니다;
 VarType getType() const override {
 return INTEGER;
 }
};

class StrVar : public Var {
public:
 StrVar(std::string s) : value(s) {}
 std::문자열 값입니다;
 VarType getType() const override {
 return STRING;
 }
};

class ArrayVar : public Var {
public:
 std::vector<std::unique_ptr<Var>> 엘리먼트;
 VarType getType() const override {
 return ARRAY;
 }
 ~ArrayVar() {
 for (auto& elem : elements) {
 elem.reset();
 }
 }
};

class MapVar : public Var {
public:
 std::unordered_map<std::string, std::unique_ptr<Var>> 엘리먼트;
 VarType getType() const override {
 return MAP;
 }
 ~MapVar() {
 for (auto& elem : elements) {
 elem.second.reset();
 }
 }
};

int main() {
 // 정수 변수를 생성합니다.
 auto i = std::make_unique<IntVar>(42);
 
 // 문자열 변수 생성
 auto s = std::make_unique<StrVar>("Hello, world!");
 
 // 배열 변수 생성
 auto a = std::make_unique<ArrayVar>();
 a->getType(); // ARRAY
 a->elements.emplace_back(std::move(i));
 a->elements.emplace_back(std::move(s));
 
 // 지도 변수 생성
 auto m = std::make_unique<MapVar>();
 m->getType(); // MAP
 m->elements["int"] = std::move(i);
 m->elements["str"] = std::move(s);
 
 // 변수 사용
 std::cout << dynamic_cast<IntVar*>(a->elements[0].get())->value << std::endl;
 std::cout << dynamic_cast<StrVar*>(a->elements[1].get())->value << std::endl;
 std::cout << dynamic_cast<IntVar*>(m->elements["int"].get())->value << std::endl;
 std::cout << dynamic_cast<StrVar*>(m->elements["str"].get())->value << std::endl;
 
 // 메모리를 정리할 필요가 없습니다 - 스마트 포인터가 자동으로 처리합니다.
 
 반환 0;
}
```
