public class FloodControl {
    private Message lastMessage;

    public void run(Message message) throws IOException {
        if (lastMessage != null && message.chatId == lastMessage.chatId) {
            if (message.date - lastMessage.date < 4000) { // 4 seconds in milliseconds
                return; // Ignore the message
            }
        }
        lastMessage = message; // Store the current message as the last message
    }
}
