def calculate_quantities(target_weight):
    # Initialize output array
    output = []

    # Identifier needs: at least 2 of type 1, 1 of type 2, 1 of type 3
    base_weight = 2*1 + 3*1 + 4*1
    if target_weight < base_weight:
        return "No solution. Target weight can't be less than the minimum total weight of all types of pears."

    remaining_weight = target_weight - base_weight

    # iterate through remaining weight
    for i in range(remaining_weight + 1):
        for j in range(remaining_weight + 1):
            for k in range(remaining_weight + 1):
                if 2*i + 3*j + 4*k == remaining_weight:
                    output.append((2 + i, 1 + j, 1 + k))
