Here is the equivalent C++ code. 

```C++
#include<bits/stdc++.h>
using namespace std;

class Solution {
    public:
        string decimalToBinary(int decimal) {
            string binary = bitset<32> (decimal).to_string();
            return "db" + binary.substr(binary.find_first_not_of('0')) + "db";
        }
};

int main() {
    Solution sol;
    cout<<sol.decimalToBinary(15)<<endl;
    cout<<sol.decimalToBinary(32)<<endl;
    return 0;
}
```

Please note the use of `bitset` in the C++ solution. By default, `bitset` gives a binary string of length equal to the number of bits that the C++ int data type holds (32 bits in this case). So the function `find_first_not_of('0')` is used to remove the leading zeros from the binary string. 

