            print("Account not found.")
            return
        }
        accounts[accountIndex].balance += amount
    }

    // Withdraw funds from the specified account
    func withdrawFunds(accountNumber: Int, amount: Double) {
        guard let accountIndex = accounts.firstIndex(where: { $0.accountNumber == accountNumber }) else {
            print("Account not found.")
            return
        }
        guard accounts[accountIndex].balance >= amount else {
            print("Insufficient funds.")
            return
        }
        accounts[accountIndex].balance -= amount
    }

    // Transfer funds from one account to another
    func transferFunds(fromAccount: Int, toAccount: Int, amount: Double) {
        guard let fromIndex = accounts.firstIndex(where: { $0.accountNumber == fromAccount }),
              let toIndex = accounts.firstIndex(where: { $0.accountNumber == toAccount }) else {
            print("One or both accounts not found.")
            return
        }
        guard accounts[fromIndex].balance >= amount else {
            print("Insufficient funds for transfer.")
            return
        }
        accounts[fromIndex].balance -= amount
        accounts[toIndex].balance += amount
    }

