    {
        if (commentLikes.ContainsKey((postId, commentId)))
        {
            return commentLikes[(postId, commentId)].Contains(supportId);
        }
        return false;
    }

    public int GetLikes(int postId, int commentId)
    {
        if (commentLikes.ContainsKey((postId, commentId)))
        {
            return commentLikes[(postId, commentId)].Count;
        }
        return 0;
    }

    public bool AddLike(Like like)
    {
        if (!commentLikes.ContainsKey((like.PostId, like.CommentId)))
        {
            commentLikes[(like.PostId, like.CommentId)] = new HashSet<int>();
        }
        return commentLikes[(like.PostId, like.CommentId)].Add(like.SupportId);
    }

    public bool DeleteLike(int postId, int commentId, int supportId)
    {
        if (commentLikes.ContainsKey((postId, commentId)))
        {
            return commentLikes[(postId, commentId)].Remove(supportId);
        }
        return false;
    }
}
