```

```python
from google.cloud import storage

def create_client():
    return storage.Client()

def upload_blob(bucket_name, source_file_name, destination_blob_name):
    storage_client = create_client()
    bucket = storage_client.bucket(bucket_name)
    blob = bucket.blob(destination_blob_name)

    try:
        blob.upload_from_filename(source_file_name)
    except Exception as ex:
        print(f'Error occurred while uploading file: {ex}')

def download_blob(bucket_name, source_blob_name, destination_file_name):
    storage_client = create_client()
    bucket = storage_client.bucket(bucket_name)
    blob = bucket.blob(source_blob_name)

    try:
        blob.download_to_filename(destination_file_name)
    except Exception as ex:
        print(f'Error occurred while downloading file: {ex}')

def list_blobs(bucket_name):
    storage_client = create_client()
    try:
        blobs = storage_client.list_blobs(bucket_name)

        for blob in blobs:
            print(blob.name)
    except Exception as ex:
        print(f'Error occurred while listing blobs: {ex}')

def rename_blob(bucket_name, blob_name, new_name):
    storage_client = create_client()
    bucket = storage_client.bucket(bucket_name)
    blob = bucket.blob(blob_name)

    try:
        new_blob = bucket.rename_blob(blob, new_name)
        print(new_blob.name)
    except Exception as ex:
        print(f'Error occurred while renaming blob: {ex}')

def move_blob(current_bucket, blob_name, new_bucket):
    storage_client = create_client()
    source_bucket = storage_client.bucket(current_bucket)
    blob = source_bucket.blob(blob_name)
    destination_bucket = storage_client.bucket(new_bucket)

    try:
        source_bucket.copy_blob(blob, destination_bucket, blob_name)
        blob.delete()
    except Exception as ex:
        print(f'Error occurred while moving blob: {ex}')

def manage_versions(bucket_name):
    storage_client = create_client()
    bucket = storage_client.get_bucket(bucket_name)

    try:
        bucket.versioning_enabled = True
        bucket.patch()
    except Exception as ex:
        print(f'Error occurred while managing versions: {ex}')
