```python
class TextOperations:
    @staticmethod
    def findDuplicates(strings):
        # Create a dictionary to store the counts
        count_dict = {}
        for string in strings:
            if string in count_dict:
                count_dict[string] += 1
            else:
                count_dict[string] = 1

        # Find the strings with counts greater than 1
        duplicates = [string for string, count in count_dict.items() if count > 1]

        return duplicates
