package main

import (
	"fmt"
	"math"
)

func intersperse(numbers []int, delimiter int) []int {
	var result []int
	for i, num := range numbers {
		if delimiter < 0 && i == int(math.Abs(float64(delimiter))) {
			continue
		}
		result = append(result, num)
		if i != len(numbers) - 1 {
			result = append(result, int(math.Abs(float64(delimiter))))
		}
	}
	return result
}

func main() {
	fmt.Println(intersperse([]int{}, 4))       // Output: []
	fmt.Println(intersperse([]int{1, 2, 3}, 4)) // Output: [1 4 2 4 3]
	fmt.Println(intersperse([]int{1, 2, 3}, -2))//  Output: [1 2 3]
}
```

