class Solution:
    def diameterOfBinaryTree(self, root: TreeNode) -> int:
        self.diameter = 0  # Initialize the diameter to 0

        def max_depth(node: TreeNode) -> int:
            if not node:
                return 0
            left_depth = max_depth(node.left)
            right_depth = max_depth(node.right)
            self.diameter = max(self.diameter, left_depth + right_depth)  # Update the diameter
            return 1 + max(left_depth, right_depth)

        max_depth(root)  # Call the helper function to calculate the maximum depth
        return self.diameter
