```csharp
using System;

namespace Livraria.Domain.Services
{
    public class EmprestimoService : IEmprestimoService
    {
        public decimal CalculateFine(int daysOverdue)
        {
            decimal fine = 0;

            if (daysOverdue <= 7)
            {
                fine = 0.50m * daysOverdue;
            }
            else if (daysOverdue <= 14)
            {
                fine = 7 * 0.50m + (daysOverdue - 7) * 1.00m;
            }
