func convertToTitleCase(_ inputString: String, _ exceptionWords: [String]) -> String {
    let words = inputString.components(separatedBy: " ")
    let titleCaseWords = words.map { word -> String in
        if exceptionWords.contains(word.lowercased()) {
            return word.lowercased()
        } else {
            return word.prefix(1).uppercased() + word.dropFirst().lowercased()
        }
    }
    return titleCaseWords.joined(separator: " ")
}

