```csharp
using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Linq;
using System.Reflection;

namespace CustomSorting
{
    public static class CustomSort
    {
        public static IEnumerable<T> SortByProperty<T>(IEnumerable<T> collection, string propertyName, Direction direction)
        {
            PropertyInfo propInfo = typeof(T).GetProperty(propertyName);
            if (propInfo == null)
            {
                throw new ArgumentException($"Property '{propertyName}' does not exist on type '{typeof(T).Name}'.");
            }

            if (direction == Direction.Ascending)
            {
                return collection.OrderBy(x => propInfo.GetValue(x, null));
