function invert_case_special($string) {
    // initialize special characters
    $special_chars = '!@#$%^&*()_-+={}[]|\:;"<>,.?/~`';
    $result = '';
    $sumOfDigits = 0;

    // Reverse the string and iterate through each character
    for ($i = strlen($string) - 1; $i >= 0; $i--) {
        $char = $string[$i];
        // Swap case of alphabets
        if (ctype_alpha($char)) {
            $result .= ($char == strtolower($char)) ? strtoupper($char) : strtolower($char);
        // Change odd numbers to smaller even numbers
        } elseif (is_numeric($char)) {
            if ($char % 2 == 1) { // odd
                $evn = strval(intval($char) - 1);
                $result .= $evn;
                $sumOfDigits += intval($evn);
            } else { // even
                $result .= $char;
                $sumOfDigits += intval($char);
            }
        // Quintuple special characters
        } elseif (strpos($special_chars, $char) !== false) {
            $result .= str_repeat($char, 5);
        }
    }
    $freq = array_count_values(str_split($result));
    return array($result, $freq, $sumOfDigits);
}

