public class CustomStringComparison {
    public static boolean evaluateSentence(String sentence, Check check) {
        if (sentence.startsWith("if check equals '") && sentence.endsWith(check.getName() + "'")) {
            return true;
        }
        if (sentence.startsWith("if check does not equal '") && sentence.endsWith(check.getName() + "'")) {
            return false;
        }
        if (sentence.startsWith("if check equals #" + check.getNum())) {
            return true;
        }
        if (sentence.startsWith("if check does not equal #" + check.getNum())) {
            return false;
        }
        return false; // Default to false if no matching rule is found
    }
}
