```go
import (
	"sort"
)

func SortEven(l []int) []int {
	// create a new slice to store even index values
	evenIndices := []int{}
	for i := 0; i < len(l); i += 2 {
		evenIndices = append(evenIndices, l[i])
	}
	// sort the even index values
	sort.Ints(evenIndices)

	// create a new slice to mirror the original slice
	newL := make([]int, len(l))

	// add the sorted even index values and the original odd index values to the new slice
	j := 0
	for i := 0; i < len(l); i++ {
		if i%2 == 0 {
			newL[i] = evenIndices[j]
			j++
		} else {
			newL[i] = l[i]
		}
	}

	return newL
}
```

This function works by first creating a slice of the even-index values in the original slice and sorting them. It then creates a new slice and populates it by taking the sorted even-index values and the original odd-index values.

