import os

class Node:
    def __init__(self, name):
        self.name = name
        self.children = []

class FileSystem:
    def __init__(self):
        self.root = Node('/')
        self.current = self.root

    def cd(self, directory):
        if directory == '..':
            if self.current != self.root:
                self.current = self._get_parent(self.current)
        else:
            child = self._get_child(self.current, directory)
            if child:
                self.current = child

    def ls(self):
        for child in self.current.children:
            print(child.name)

    def pwd(self):
        path = self._get_path(self.current)
        print(path)

    def _get_child(self, node, name):
        for child in node.children:
            if child.name == name:
                return child
        return None

    def _get_parent(self, node):
        return node.parent

    def _get_path(self, node):
        path = []
        while node:
            path.insert(0, node.name)
            node = node.parent
        return '/' + '/'.join(path)

# Usage
fs = FileSystem()
fs.cd('documents')
fs.ls()
fs.cd('..')
fs.pwd()
```

In Python, you can create a recursive function to calculate the factorial of a number by defining a function that calls itself within its own definition. In the case of calculating factorials, the number (n) is multiplied by the factorial of the number minus one (n-1). This continues until n equals 0, in which case the function returns 1 (since the factorial of 0 is 1). Here's a sample implementation:

```python
def factorial(n):
    # Base case: The factorial of 0 is 1
    if n == 0:
        return 1
    # Recursive case: n * factorial of (n-1)
    else:
        return n * factorial(n-1)
```

You should always check that the input is a positive integer as factorials are only defined for such numbers. If the input is negative or is not integer, you can raise an exception or return an error message. For example:

```python
def factorial(n):
    # Check if n is an integer
    if not isinstance(n, int):
        print("Error: Factorial is only defined for integers.")
        return None
    # Check if n is negative
    elif n < 0:
        print("Error: Factorial is not defined for negative numbers.")
        return None
    # Base case
    elif n == 0:
        return 1
    # Recursive case
    else:
        return n * factorial(n-1)
```

