Here's an example of how you could implement such a class in JavaScript using ES6 syntax, closures for private methods, and Proxies for safe data handling. 

Please note that true private methods are not really possible in JavaScript without using closures or some other workaround. ES2019 introduced `#` notation for private fields, but there's no private methods yet, hence we're using closure to achieve this functionality.

```javascript
class UserRole {
    constructor() {

        // Define private methods using closures
        // This method can only be accessed within the constructor
        const privateMethod = () => {
            console.log("Executing private method...");
        };

        // Public method can call private method
        this.publicMethod = (conditionalCircumstances) => {
            if (conditionalCircumstances) {
                privateMethod();
            } else {
                console.log("Conditional Circumstances not met.")
            }
        }

        // Proxy for safe data handling
        // Define private data 
        let userData = {
            role: ''
        };

        // Define Proxy
        this.user = new Proxy(userData, {
            get: function(target, property) {
                if (property in target) {
                    return target[property];
                } else {
                    throw new Error(`Property ${property} does not exist on userData.`);
                }
            },
            set: function(target, property, value) {
                if (property === 'role') {
                    if (['admin', 'user', 'guest'].includes(value)) {
                        target[property] = value;
                    } else {
                        throw new Error(`Invalid role: ${value}`);
                    }
                } else {
                    throw new Error(`Property ${property} does not exist on userData.`);
                }
            }
        });

    }
}

let testUserRole = new UserRole();

// Accessing private data without error
try {
    testUserRole.user.role = 'admin';
    console.log(testUserRole.user.role); // Expected Output: admin
} catch (error) {
    console.error(error);
}

// Accessing private data with error
try {
    testUserRole.user.role = 'unknown';
} catch (error) {
    console.error(error); // Expected Output: Error: Invalid role: unknown
}

// Accessing unknown property
try {
    console.log(testUserRole.user.unknown);
} catch (error) {
    console.error(error); // Expected Output: Error: Property unknown does not exist on userData.
}

// Trying to call private method via object
if(typeof testUserRole.privateMethod === 'function'){
    console.log("privateMethod exists and is callable via object");
}else{
    console.log("privateMethod doesn't exist or is not callable via object"); // Expected Output
}

// Calling private method via public method
testUserRole.publicMethod(true); // Expected Output: Executing private method...
testUserRole.publicMethod(false); // Expected Output: Conditional Circumstances not met. 
```

In the above, the `get` and `set` methods of the `Proxy` are used for safe data handling. They essentially intercept any access to or modification of properties on the `userData` object and can enforce certain rules (such as, in this case, validating the user role). 

We also use the try-catch blocks for error handling. If there is an exception within the try block, the catch block will be executed.

