Here is the Python code which uses the Miller-Rabin primality test, as well as memoization, to compute the k-th prime number in a modified Fibonacci sequence:

```python
import random

# Miller-Rabin primality test
def miller_rabin(n, k=5): 
    if n < 2:
        return False
    for _ in range(k):
        a = random.randint(1, n - 1)
        x = pow(a, n - 1, n) 
        if x != 1 and x != n - 1: 
            j = 1
            while j < n - 1 and x != n - 1:
                x = pow(x, 2, n)
                if x == 1:
                    return False 
                j += 1
            if x != n - 1:
                return False
    return True

# Modified Fibonacci sequence using dynamic programming
def fibfib(n, memo):
    if memo[n] is not None:
        return memo[n]
    if n < 0:
        result = fibfib(n+3, memo) - fibfib(n+2, memo) - fibfib(n+1, memo)
    else:
        result = fibfib(n-1, memo) + fibfib(n-2, memo) + fibfib(n-3, memo)
    memo[n] = result
    return result

# Function to compute the k-th prime element of the sequence
def millerRabin_fibfib(k):
    i, prime_count = 0, 0
    memo = [None] * 100000
    memo[0], memo[1], memo[2] = 0, 0, 1
    while prime_count < k:
        i += 1
        fib_num = fibfib(i, memo)
        if miller_rabin(fib_num):
            prime_count += 1
    return fibfib(i-1, memo)

# Test cases
print(millerRabin_fibfib(1))
print(millerRabin_fibfib(3))
print(millerRabin_fibfib(-1))
```
