    private static void sortMultiThreaded(int[] a, int[] aux, int lo, int hi) throws ExecutionException, InterruptedException {
        if(hi <= lo) return;

        if(hi - lo <= THRESHOLD) {  // switch to single threaded mode if array size is small
            sortSingleThreaded(a, aux, lo, hi);
        } else {
            int mid = lo + (hi - lo) / 2;

            // recursively sort halves of input array
            Future<?> left = pool.submit(() -> {
                try {
                    sortMultiThreaded(a, aux, lo, mid);
                } catch (ExecutionException | InterruptedException e) {
                    e.printStackTrace();
                }
            });

            Future<?> right = pool.submit(() -> {
                try {
                    sortMultiThreaded(a, aux, mid + 1, hi);
                } catch (ExecutionException | InterruptedException e) {
                    e.printStackTrace();
                }
            });

            // wait for tasks completion
            left.get();
            right.get();

            merge(a, aux, lo, mid, hi);
        }
    }
