typealias Point = (x: Double, y: Double)
typealias LineSegment = (start: Point, end: Point)

func calculateEquipotentialLines(electricPotentialFunction: ElectricPotentialFunction, xRange: ClosedRange<Double>, yRange: ClosedRange<Double>, step: Double) -> [LineSegment] {
    var equipotentialLines: [LineSegment] = []

    for x in stride(from: xRange.lowerBound, through: xRange.upperBound, by: step) {
        for y in stride(from: yRange.lowerBound, through: yRange.upperBound, by: step) {
            let potential = electricPotentialFunction(x, y)
            let startX = x - step / 2
            let endX = x + step / 2
            let startY = y - step / 2
            let endY = y + step / 2

            if x + step <= xRange.upperBound {
                let potentialRight = electricPotentialFunction(x + step, y)
                if potential * potentialRight <= 0 {
                    equipotentialLines.append((start: (x: endX, y: startY), end: (x: endX, y: endY)))
                }
            }
            if y + step <= yRange.upperBound {
                let potentialUp = electricPotentialFunction(x, y + step)
                if potential * potentialUp <= 0 {
                    equipotentialLines.append((start: (x: startX, y: endY), end: (x: endX, y: endY)))
                }
            }
        }
    }

    return equipotentialLines
}
```

This solution defines the `calculateEquipotentialLines` function, which iterates through the 2D space defined by the given ranges and step size. For each point in the space, it calculates the electric potential and checks for potential changes in the neighboring points to identify the equipotential lines. The function returns an array of line segments representing the equipotential lines in the space.

